class _VerifiedSuperAdminDrawerEntry extends StatefulWidget {
  const _VerifiedSuperAdminDrawerEntry();

  @override
  State<_VerifiedSuperAdminDrawerEntry> createState() =>
      _VerifiedSuperAdminDrawerEntryState();
}

class _VerifiedSuperAdminDrawerEntryState
    extends State<_VerifiedSuperAdminDrawerEntry> {
  late final Future<SuperAdminAccessResult> _accessCheck;

  @override
  void initState() {
    super.initState();

    _accessCheck = SuperAdminAccessService().checkCurrentAccess(
      forceRefreshToken: true,
    );
  }

  @override
  Widget build(BuildContext context) {
    return FutureBuilder<SuperAdminAccessResult>(
      future: _accessCheck,
      builder:
          (
            BuildContext context,
            AsyncSnapshot<SuperAdminAccessResult> snapshot,
          ) {
            final SuperAdminAccessResult? result = snapshot.data;

            if (result == null || !result.isSuperAdmin) {
              return const SizedBox.shrink();
            }

            return ListTile(
              leading: const Icon(
                Icons.admin_panel_settings_rounded,
                color: Color(0xFFFFD600),
              ),
              title: const Text(
                'Super Admin',
                style: TextStyle(fontWeight: FontWeight.bold),
              ),
              subtitle: const Text('Owner / global platform controls'),
              onTap: () {
                Navigator.pop(context);

                Navigator.push(
                  context,
                  MaterialPageRoute<void>(
                    builder: (_) => const SuperAdminAccessGuardScreen(),
                  ),
                );
              },
            );
          },
    );
  }
}
